package com.crazy4lamb.crmbi.controller;

import static com.crazy4lamb.crmbi.controller.AuthController.user;
import static com.crazy4lamb.crmbi.core.Api.ok;
import com.crazy4lamb.crmbi.core.*;
import com.zaxxer.hikari.HikariDataSource;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/sys")
public class SystemController {
  private final Db db; private final PasswordEncoder passwords; private final HikariDataSource pool;
  public SystemController(Db db, PasswordEncoder passwords, javax.sql.DataSource source) { this.db=db; this.passwords=passwords; this.pool=(HikariDataSource)source; }
  @GetMapping("/roles") public Map<String,Object> roles(HttpServletRequest r){admin(user(r));return db.tx(user(r),x->{List<Map<String,Object>>rows=db.many("select r.*,(select count(*)::int from sys_user u where u.role_code=r.code) user_count from sys_role r order by sort_no");rows.forEach(v->v.put("userCount",v.remove("user_count")));return ok(rows);});}
  @GetMapping("/users") public Map<String,Object> users(HttpServletRequest r){admin(user(r));return db.tx(user(r),x->ok(db.many("select u.id,u.username,u.real_name,u.role_code,r.name role_name,u.dept,u.phone,u.email,u.data_scope,u.status,u.last_login_at,u.created_at from sys_user u left join sys_role r on r.code=u.role_code order by u.id")));}
  @PostMapping("/users") public Map<String,Object> create(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(user(r));if(b.get("username")==null||b.get("real_name")==null||b.get("role_code")==null)throw ApiException.bad("用户名/姓名/角色必填");return db.tx(user(r),x->{Number id=db.insertId("insert into sys_user(username,password,real_name,role_code,dept,phone,email,data_scope,status) values(:username,:password,:name,:role,:dept,:phone,:email,:scope,:status)",params("username",b.get("username"),"password",passwords.encode(String.valueOf(b.getOrDefault("password","123456"))),"name",b.get("real_name"),"role",b.get("role_code"),"dept",b.get("dept"),"phone",b.get("phone"),"email",b.get("email"),"scope",b.getOrDefault("data_scope","self"),"status",b.getOrDefault("status","1")));return ok(Map.of("id",id),"用户已创建");});}
  @PutMapping("/users/{id}") public Map<String,Object> update(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest r){admin(user(r));return db.tx(user(r),x->{db.update("update sys_user set real_name=coalesce(:name,real_name),role_code=coalesce(:role,role_code),dept=coalesce(:dept,dept),phone=coalesce(:phone,phone),email=coalesce(:email,email),data_scope=coalesce(:scope,data_scope),status=coalesce(:status,status) where id=:id",params("name",b.get("real_name"),"role",b.get("role_code"),"dept",b.get("dept"),"phone",b.get("phone"),"email",b.get("email"),"scope",b.get("data_scope"),"status",b.get("status"),"id",id));if(b.get("password")!=null)db.update("update sys_user set password=:password where id=:id",Map.of("password",passwords.encode(String.valueOf(b.get("password"))),"id",id));return ok(null,"已保存");});}
  @DeleteMapping("/users/{id}") public Map<String,Object> delete(@PathVariable int id,HttpServletRequest r){UserPrincipal u=user(r);admin(u);if(id==u.id())throw ApiException.bad("不能删除当前登录账号");return db.tx(u,x->{db.update("delete from sys_user where id=:id",Map.of("id",id));return ok(null,"已删除");});}
  @GetMapping("/acl") public Map<String,Object> acl(HttpServletRequest r){admin(user(r));return db.tx(user(r),x->{List<Map<String,Object>>roles=db.many("select code,name from sys_role order by sort_no"),menus=db.many("select code,name,parent_code from sys_menu order by sort_no"),cards=db.many("select code,name from bi_widget where widget_type='card'"),charts=db.many("select code,name from bi_widget where widget_type='chart'"),reports=db.many("select id::text code,name from rpt_report"),dashboards=db.many("select code,name from bi_dashboard"),rows=db.many("select role_code,res_type,res_key from sys_acl");Map<String,Object>matrix=new LinkedHashMap<>();for(Map<String,Object>role:roles){Map<String,List<String>>p=new LinkedHashMap<>();for(String t:List.of("menu","action","card","chart","report","dashboard"))p.put(t,new ArrayList<>());matrix.put(String.valueOf(role.get("code")),p);}for(Map<String,Object>row:rows){Map<String,List<String>>p=(Map<String,List<String>>)matrix.get(String.valueOf(row.get("role_code")));if(p!=null)p.computeIfAbsent(String.valueOf(row.get("res_type")),k->new ArrayList<>()).add(String.valueOf(row.get("res_key")));}List<Map<String,Object>>actions=List.of("customer:add","customer:edit","customer:delete","customer-pool:claim","customer-pool:release","lead:add","lead:claim","lead:assign","lead:edit","opp:add","opp:edit","payment:add","contract:add","contract:edit","order:add","order:edit","follow:add","report:design","widget:design","metric:design","task:run","task:edit","user:edit").stream().map(v->Map.<String,Object>of("code",v,"name",v)).toList();return ok(Map.of("roles",roles,"resources",Map.of("menu",menus,"action",actions,"card",cards,"chart",charts,"report",reports,"dashboard",dashboards),"matrix",matrix));});}
  @PostMapping("/acl") public Map<String,Object> aclSave(@RequestBody Map<String,Object>b,HttpServletRequest r){admin(user(r));return db.tx(user(r),x->{Map<String,Object>p=Map.of("role",b.get("roleCode"),"type",b.get("resType"),"key",b.get("resKey"));if(Boolean.TRUE.equals(b.get("enabled")))db.update("insert into sys_acl(role_code,res_type,res_key) values(:role,:type,:key) on conflict do nothing",p);else db.update("delete from sys_acl where role_code=:role and res_type=:type and res_key=:key",p);return ok(null,"权限已更新");});}
  @GetMapping("/stats") public Map<String,Object> stats(HttpServletRequest r){return db.tx(user(r),x->{List<String>tables=List.of("sys_user","crm_customer","crm_lead","crm_lead_pool","crm_opportunity","crm_contract","crm_order","crm_follow_up","rpt_dataset","rpt_report","bi_metric","bi_metric_value","bi_widget","bi_dashboard","bi_task","bi_task_log");Map<String,Object>counts=new LinkedHashMap<>();for(String table:tables)counts.put(table,db.one("select count(*) c from "+table).get("c"));Map<String,Object>v=db.one("select version() v,current_database() d,current_date today");return ok(Map.of("db",Map.of("mode","pg","label","PostgreSQL @ "+v.get("d"),"version",v.get("v")),"today",v.get("today"),"counts",counts,"backend","Spring Boot 3.5.8 / Java 21"));});}
  @GetMapping("/postgres") public Map<String,Object> postgres(HttpServletRequest r){admin(user(r));return db.tx(user(r),x->{Map<String,Object>database=db.one("select version() version,current_database() name,current_user \"user\",pg_database_size(current_database()) bytes,(select rolsuper from pg_roles where rolname=current_user) superuser,(select rolbypassrls from pg_roles where rolname=current_user) bypass_rls"),snapshot=db.one("select *,source_version>refreshed_version stale from bi_refresh_state where id=1"),audit=db.one("select count(*)::int records,max(occurred_at) latest from crm_audit");List<Map<String,Object>>indexes=db.many("select indexname,tablename,indexdef from pg_indexes where schemaname='public' order by tablename,indexname"),policies=db.many("select tablename,policyname,cmd from pg_policies where schemaname='public'"),migrations=db.many("select version,applied_at from app_migration order by version"),tables=db.many("select relname,n_live_tup,seq_scan,idx_scan from pg_stat_user_tables where schemaname='public' and relname like 'crm_%'");Map<String,Object>poolStats=Map.of("total",pool.getHikariPoolMXBean().getTotalConnections(),"active",pool.getHikariPoolMXBean().getActiveConnections(),"idle",pool.getHikariPoolMXBean().getIdleConnections(),"waiting",pool.getHikariPoolMXBean().getThreadsAwaitingConnection(),"max",pool.getMaximumPoolSize());Object plan=db.many("explain(analyze,buffers,format json) select id from crm_customer where name ilike '%科技%' limit 20").getFirst().values().iterator().next();Map<String,Object>result=new LinkedHashMap<>();result.put("enabled",true);result.put("database",database);result.put("pool",poolStats);result.put("indexes",indexes);result.put("policies",policies);result.put("snapshot",snapshot);result.put("audit",audit);result.put("migrations",migrations);result.put("tables",tables);result.put("searchPlan",plan);result.put("backend",Map.of("framework","Spring Boot 3.5.8","java","21","dataAccess","Spring JDBC + HikariCP"));return ok(result);});}
  @PostMapping("/postgres/refresh") public Map<String,Object> refresh(HttpServletRequest r){admin(user(r));return db.tx(user(r),x->{Object value=db.one("select bi_refresh_sales() refreshed").get("refreshed");return ok(Map.of("refreshed",value),Boolean.TRUE.equals(value)?"经营快照已刷新":"当前正在刷新，请稍后查看");});}
  @GetMapping("/oper-logs") public Map<String,Object> logs(HttpServletRequest r){admin(user(r));return db.tx(user(r),x->ok(db.many("select * from sys_oper_log order by id desc limit 100")));}
  private static void admin(UserPrincipal u){if(!u.admin())throw ApiException.forbidden("无权限：仅系统管理员可访问");}
  private static Map<String,Object>params(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<v.length;i+=2)m.put(String.valueOf(v[i]),v[i+1]);return m;}
}
